import { useCallback } from 'react';
import { useLanguage, type CopyParams, type SiteLanguage } from '../portfolio/LanguageProvider';
import { interpolate } from './terms';

/**
 * The workspace dictionary: every string the Plimsoll application itself
 * authors, in both languages.
 *
 * The public shell already has its own dictionary for the public pages; this is
 * the same discipline applied to the tool. English is the source, the Chinese
 * dictionary is checked for completeness and shape by the type system, keys are
 * dotted and flat so a key is greppable from the component that prints it, and
 * interpolation is exactly the shell's `{slot}` rule.
 *
 * The split from the laboratory dictionary is deliberate and load-bearing.
 * `portfolio.tsx` imports `App`, which the tool route lazy-loads; if the
 * laboratory's copy lived here it would be pulled into the same eager chunk as
 * the whole workspace, and the public pages would ship Three.js's neighbours.
 * Laboratory strings therefore live in `./lab`, which only `damageLab/*`
 * imports, and that module is itself dynamically imported by the lab route.
 *
 * Nothing here is a runtime lookup framework: `t` is a typed function over two
 * frozen objects. There is no DOM rewriting, no translation pass over rendered
 * text, and no second preference store — `useLanguage()` is the single language
 * state and the single `setLanguage`.
 *
 * The categories below are ordered the way a reader meets them: the workspace
 * shell, then the library, then the workbench chapters, then the run and report
 * pages, then the shared reading vocabulary (stages, statuses, units,
 * diagnostics) that all of those print.
 */

/* ------------------------------------------------------------------------- */
/* English — the source dictionary                                            */
/* ------------------------------------------------------------------------- */

