/** Every string the workspace can print. */
export type WorkspaceKey = keyof typeof EN;

/**
 * The shape both dictionaries must have.
 *
 * `string` rather than the literal type English infers, so the Chinese side is
 * checked for completeness and shape — the thing that actually goes wrong — and
 * not for being the identical string.
 */
export type WorkspaceDictionary = Readonly<Record<WorkspaceKey, string>>;

/**
 * The order the report presents the metrics it knows, taken from the
 * dictionary's own order rather than a second list that could drift from it.
 *
 * A stage card reads payload order otherwise, which is not stable between runs
 * and made two runs of the same project hard to compare side by side. Metrics
 * this registry does not know keep their payload order and come after these.
 */
export const DATA_LABEL_ORDER: readonly string[] = Object.keys(EN)
  .filter(key => key.startsWith('data.'))
  .map(key => key.slice('data.'.length));

