/** The whole workspace dictionary for one language. */
export function workspaceDictionary(language: SiteLanguage): WorkspaceDictionary {
  return language === 'zh-CN' ? ZH : EN;
}

/**
 * The name each template's project is *saved* under.
 *
 * This is the deliberate other half of the template copy. The card on the
 * library page is application-authored UI and is bilingual; the `name` sent to
 * `createProject` becomes the project's own name in the document and on every
 * later screen, and a name a project was created under is data rather than a
 * translation target. So it is one string here, identical in both languages,
 * while `library.template.*.name` above is the card's own label.
 *
 * Keeping them apart is what lets an English reader see "Analytic box" and
 * still open a project called `解析方箱`, exactly as the Chinese reader does.
 */
export const TEMPLATE_STORED_NAMES: Readonly<Record<string, string>> = {
  analytic_box: '解析方箱',
  concept_cruiser: '概念巡洋舰（合成）',
  generic_steamer: '通用试验船',
  queen_mary_1913: 'HMS Queen Mary',
};

/** The name a project created from `key` is saved under, in either language. */
export function storedTemplateName(key: string): string {
  return TEMPLATE_STORED_NAMES[key] ?? key;
}

/**
 * One workspace message, with its `{slot}`s filled.
 *
 * An unknown key returns the key itself rather than an empty string, so a typo
 * shows up on screen as something obviously wrong instead of as a missing line.
 */
export function workspaceCopy(language: SiteLanguage, key: WorkspaceKey, params?: CopyParams): string {
  const text: string = (workspaceDictionary(language) as Record<string, string>)[key] ?? key;
  return interpolate(text, params);
}

/**
 * The workspace lookup, bound to the shell's one language state.
 *
 * A component rendered on its own — a page in a test, an editor beside the unit
 * provider — gets the English strings it has always printed, with no provider
 * and no wrapper: the same rule the public shell's default context follows, and
 * the reason every standalone English expectation stays true. The returned
 * function is stable while the language is, so a switch re-renders the words and
 * nothing else: no remount, no re-read, no queued request, no reset draft.
 */
export function useWorkspaceCopy(): (key: WorkspaceKey, params?: CopyParams) => string {
  const { language } = useLanguage();
  return useCallback((key: WorkspaceKey, params?: CopyParams) => workspaceCopy(language, key, params), [language]);
}
